insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_47_v1'
from (values
('127.259.d.1.A',3,'An analyst uses survey results to estimate how many customers will renew a membership. This applies math to a:','["Problem from business and society", "Puzzle with no use", "Drawing contest", "Classroom game"]'::jsonb,0,'Statistics solves real problems.','original'),
('127.259.d.1.A',4,'A store manager studies daily returns data to cut losses from damaged goods. This is mathematics applied to:','["An art project", "A real operational problem", "A theoretical proof", "A word game"]'::jsonb,1,'Data guides business action.','original'),
('127.259.d.1.B',3,'In a problem-solving model, the step after analyzing the given information is to:','["Hide the data", "Guess an answer", "Formulate a plan or strategy", "Stop working"]'::jsonb,2,'Plan follows analysis.','original'),
('127.259.d.1.B',4,'A student gets an average customer wait time of -3 minutes. Which step of the problem-solving model catches this error?','["Reading the problem", "Choosing a color", "Making a poster", "Evaluating the reasonableness of the solution"]'::jsonb,3,'Waiting time cannot be negative.','original'),
('127.259.d.1.C',3,'To compute the mean of 500 sales figures quickly, the best tool is:','["Spreadsheet software", "A ruler", "Counting on fingers", "A protractor"]'::jsonb,0,'Spreadsheets handle large data sets.','original'),
('127.259.d.1.C',4,'Checking that a computed standard deviation is close to what a quick range-divided-by-four estimate suggests uses:','["Number lines only", "Mental math and estimation", "Random selection", "Tally marks only"]'::jsonb,1,'Estimates check results.','original'),
('127.259.d.1.D',3,'Describing what a sample mean says about a customer group in clear words is:','["Skipping analysis", "Hiding results", "Communicating a mathematical idea", "Copying data"]'::jsonb,2,'Explanation is communication.','original'),
('127.259.d.1.D',4,'A strong statistical summary for a manager states the result, its meaning, and:','["A rumor", "A pun", "An unrelated opinion", "Its implication for a decision"]'::jsonb,3,'Implications make results useful.','original'),
('127.259.d.1.E',3,'A histogram of customer ages is a:','["Representation that organizes data", "Password", "Contract", "Receipt"]'::jsonb,0,'Graphs organize and display data.','original'),
('127.259.d.1.E',4,'To show the share of sales from each region, an analyst could create:','["A map of parking", "A pie chart or a table of percentages", "A time card", "A recipe"]'::jsonb,1,'Part-to-whole displays fit shares.','original'),
('127.259.d.1.F',3,'Noticing that sales rise as advertising spending rises is analyzing:','["A coincidence only", "A spelling pattern", "A relationship between two variables", "A single constant"]'::jsonb,2,'Relationships connect variables.','original'),
('127.259.d.1.F',4,'Linking a regression equation to the line drawn through a scatterplot connects:','["Two languages", "Two random facts", "Unrelated ideas", "Different representations of one relationship"]'::jsonb,3,'Equation and graph agree.','original'),
('127.259.d.1.G',3,'Presenting a chart along with the calculations behind it helps to:','["Justify a mathematical argument", "Remove evidence", "Avoid questions", "Shorten the report"]'::jsonb,0,'Showing work supports claims.','original'),
('127.259.d.1.G',4,'The best justification for choosing the median over the mean for home prices is that the data contain:','["Only small numbers", "Extreme values that distort the mean", "Equal values", "No numbers"]'::jsonb,1,'Outliers pull the mean.','original'),
('127.259.d.2.A',3,'Risk management is the process of identifying, assessing, and:','["Increasing losses", "Ignoring threats", "Controlling risks to a business", "Creating new risks"]'::jsonb,2,'The process manages exposure.','original'),
('127.259.d.2.A',4,'Which pair are both common ways of handling a risk?','["Ignoring it and forgetting it", "Naming it and printing it", "Doubling it and hiding it", "Avoiding it and transferring it through insurance"]'::jsonb,3,'Avoid, reduce, transfer, accept.','original'),
('127.259.d.2.B',3,'Ethics in risk management means being honest about:','["The size and likelihood of the risks", "Only good news", "Nothing", "Only the profits"]'::jsonb,0,'Honest disclosure is ethical.','original'),
('127.259.d.2.B',4,'A manager who knows of a safety hazard but hides it to protect sales is violating:','["Nothing", "Responsibility to employees and customers", "A font rule", "A tax rule only"]'::jsonb,1,'Hiding hazards is unethical.','original'),
('127.259.d.2.C',3,'A risk manager is mainly responsible for:','["Printing flyers", "Making coffee", "Identifying exposures and recommending controls", "Cleaning offices"]'::jsonb,2,'The role centers on protecting the firm.','original'),
('127.259.d.2.C',4,'Professionals in insurance and risk fields often earn credentials such as:','["A library card", "A driver''s permit", "A swimming badge", "Chartered Property Casualty Underwriter or similar licenses"]'::jsonb,3,'Certifications show expertise.','original'),
('127.259.d.3.A',3,'An accountant forecasting next year''s consumer spending on a product line is using statistics for:','["Forecasting demand", "Painting", "Filing paper", "Typing"]'::jsonb,0,'Statistics support forecasts.','original'),
('127.259.d.3.A',4,'A firm audits 60 of 3,000 invoices at random to estimate the error rate of all invoices. This is:','["Testing every item", "Statistical sampling in auditing", "Skipping the audit", "Guessing"]'::jsonb,1,'Sampling estimates populations.','original'),
('127.259.d.3.B',3,'A government report on the unemployment rate is an example of statistics used in:','["Sports gear", "Cooking", "Economics", "Entertainment"]'::jsonb,2,'Labor reports are economic data.','original'),
('127.259.d.3.B',4,'Economists use a consumer price index to measure:','["Employee happiness", "Sunlight", "Traffic speed", "Changes in the average price of goods over time"]'::jsonb,3,'CPI tracks inflation.','original'),
('127.259.d.3.C',3,'A financial analyst compares the average return and variability of two funds. This is statistics in:','["Finance", "Art", "Gardening", "Music"]'::jsonb,0,'Return and risk are statistical.','original'),
('127.259.d.3.C',4,'In finance, the standard deviation of a stock''s returns is commonly used to measure its:','["Ticker symbol", "Risk or volatility", "Color", "Dividend date"]'::jsonb,1,'Greater spread means more risk.','original'),
('127.259.d.3.D',3,'Comparing average output per worker across plants is statistics used in:','["Poetry", "Sewing", "Management", "Dancing"]'::jsonb,2,'Managers evaluate performance with data.','original'),
('127.259.d.3.D',4,'A manager sets a control chart that signals when a process drifts. This uses statistics for:','["Naming products", "Recruiting", "Lease signing", "Quality control"]'::jsonb,3,'Control charts monitor variation.','original'),
('127.259.d.3.E',3,'A projection of sales for a new product based on test-store data uses statistics in:','["Marketing", "Welding", "Plumbing", "Roofing"]'::jsonb,0,'Test markets rely on sampling.','original'),
('127.259.d.3.E',4,'A company randomly assigns shoppers to two ad versions and compares purchase rates. This is a statistical:','["Poster", "Experiment", "Rumor", "Guess"]'::jsonb,1,'A/B tests compare groups.','original'),
('127.259.d.4',3,'Ethical use of statistics requires analysts to:','["Hide sample size", "Change the scale to impress", "Report results honestly, including unfavorable ones", "Drop data that spoil the story"]'::jsonb,2,'Honesty is basic.','original'),
('127.259.d.4',4,'A chart with a y-axis starting at 95 rather than 0 to make a 2% rise look huge is:','["Neutral", "Required", "Always correct", "Potentially misleading"]'::jsonb,3,'Truncated axes exaggerate changes.','original'),
('127.259.d.5.A',3,'Managing risk helps protect a business''s:','["Stability and ability to continue operating", "Mascot", "Slogan", "Phone number"]'::jsonb,0,'Controls guard against losses.','original'),
('127.259.d.5.A',4,'Buying business interruption insurance helps a firm stay stable after a:','["Logo change", "Fire that halts operations", "Holiday sale", "Staff lunch"]'::jsonb,1,'Insurance transfers loss.','original'),
('127.259.d.5.B',3,'A supply chain disruption is a risk that most directly affects:','["Fonts", "Wallpaper", "Business operations", "Parking lines"]'::jsonb,2,'Risks flow into operations.','original'),
('127.259.d.5.B',4,'Reducing risk in operations can include:','["Ignoring audits", "Skipping maintenance", "Removing all locks", "Training employees in safety procedures"]'::jsonb,3,'Controls reduce incidents.','original'),
('127.259.d.5.C',3,'Setting aside money to cover small, predictable losses is called:','["Self-insurance or risk retention", "Risk denial", "Risk creation", "Risk avoidance"]'::jsonb,0,'Retention accepts the loss.','original'),
('127.259.d.5.C',4,'A company that drops a dangerous product line altogether is using:','["Risk retention", "Risk avoidance", "Risk sharing", "Risk transfer"]'::jsonb,1,'Avoidance removes the exposure.','original'),
('127.259.d.6.A',3,'Statistical information is valuable in business because it helps managers make:','["Random choices", "Longer meetings", "Evidence-based decisions", "Louder arguments"]'::jsonb,2,'Data informs decisions.','original'),
('127.259.d.6.A',4,'A retailer finds that 70% of weekend buyers use coupons. This statistic can be used to:','["Cut all prices", "Rename the store", "Choose a mascot", "Plan weekend promotions"]'::jsonb,3,'Statistics shape plans.','original'),
('127.259.d.6.B',3,'An ad that says ''9 out of 10 dentists'' should prompt a reader to ask about:','["The sample size and how it was chosen", "The jingle", "The font", "The background"]'::jsonb,0,'Evaluate the source.','original'),
('127.259.d.6.B',4,'A claim that ''average customer savings are $50'' is weak if the survey included only:','["A large random sample", "Ten customers who volunteered", "Every customer", "Randomly chosen customers"]'::jsonb,1,'Volunteer samples are biased.','original'),
('127.259.d.6.C',3,'To compute a total of a column of numbers in a spreadsheet, use the function:','["NAME", "SAVE", "SUM", "PRINT"]'::jsonb,2,'SUM adds a range.','original'),
('127.259.d.6.C',4,'The spreadsheet function that returns the middle value of a data range is:','["CENTER", "MIDPOINT", "MODE.FIX", "MEDIAN"]'::jsonb,3,'MEDIAN finds the central value.','original'),
('127.259.d.6.D',3,'A good chart for showing change over several months is a:','["Line graph", "Pie chart of one slice", "Receipt", "Phone book"]'::jsonb,0,'Lines show trends.','original'),
('127.259.d.6.D',4,'A spreadsheet chart should include a title, labeled axes, and:','["No labels", "Units of measure", "A random color", "Clip art only"]'::jsonb,1,'Labels make charts readable.','original'),
('127.259.d.7.A',3,'Hair color of customers is an example of which type of variable?','["Numerical continuous", "Interval", "Categorical (qualitative)", "Ratio"]'::jsonb,2,'Colors are categories.','original'),
('127.259.d.7.A',4,'Temperature in degrees Celsius is measured on which scale?','["Nominal", "Categorical", "Ordinal", "Interval"]'::jsonb,3,'No true zero.','original'),
('127.259.d.7.B',3,'Data collected firsthand through your own survey are called:','["Primary data", "Secondary data", "Lost data", "Old data"]'::jsonb,0,'Self-collected is primary.','original'),
('127.259.d.7.B',4,'Using census tables compiled by a federal agency is an example of:','["Interview data", "Secondary data", "Experiment data", "Primary data"]'::jsonb,1,'Existing sources are secondary.','original'),
('127.259.d.7.C',3,'The entire group a researcher wants to learn about is the:','["Sample", "Bias", "Population", "Frame error"]'::jsonb,2,'The population is the whole group.','original'),
('127.259.d.7.C',4,'The 200 customers actually surveyed from 20,000 total are a:','["Census", "Parameter", "Population", "Sample"]'::jsonb,3,'A sample is a subset.','original'),
('127.259.d.7.D',3,'In simple random sampling, each member of the population has:','["An equal chance of being chosen", "A better chance if wealthy", "No chance", "A chance only if volunteering"]'::jsonb,0,'Equal probability.','original'),
('127.259.d.7.D',4,'Dividing customers by age group and then sampling randomly within each group is:','["Convenience sampling", "Stratified sampling", "Judgment sampling", "Cluster sampling"]'::jsonb,1,'Strata ensure representation.','original'),
('127.259.d.7.E',3,'A survey that misses people who have no phone has what type of error?','["Measurement error", "Arithmetic error", "Coverage error", "Typing error"]'::jsonb,2,'The frame leaves people out.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_47_v1'
from (values
('127.259.d.7.E',4,'When many selected people refuse to respond and differ from those who respond, the result is:','["Coverage error", "Sampling frame", "Rounding", "Nonresponse error"]'::jsonb,3,'Nonrespondents bias results.','original'),
('127.259.d.8',3,'A frequency distribution groups data into classes and shows:','["How many values fall in each class", "Colors only", "Prices only", "Employee names"]'::jsonb,0,'Frequencies count values.','original'),
('127.259.d.8',4,'A histogram differs from a bar chart because its bars:','["Cannot be labeled", "Represent continuous classes and touch", "Show only names", "Are separated for categories"]'::jsonb,1,'Bars are adjacent for continuous data.','original'),
('127.259.d.9.A',3,'The mean of 4, 6, 8, 10, and 12 is:','["40", "6", "8", "10"]'::jsonb,2,'Sum 40 / 5 = 8.','original'),
('127.259.d.9.A',4,'The median of 3, 5, 9, 12, and 21 is:','["5", "12", "10", "9"]'::jsonb,3,'The middle value is 9.','original'),
('127.259.d.9.B',3,'The range of 12, 20, and 35 is:','["23", "35", "12", "47"]'::jsonb,0,'35 - 12 = 23.','original'),
('127.259.d.9.B',4,'For the sample 2, 4, 6, the sample variance is:','["8", "4", "12", "2"]'::jsonb,1,'Squared deviations total 8; divide by n-1 = 2 gives 4.','original'),
('127.259.d.9.C',3,'If a data set''s mean is larger than its median, the distribution is most likely:','["Symmetric", "Skewed left", "Skewed right", "Uniform exactly"]'::jsonb,2,'A long right tail pulls the mean up.','original'),
('127.259.d.9.C',4,'A symmetric bell-shaped distribution has skewness close to:','["10", "-1", "1", "0"]'::jsonb,3,'No tilt means zero skewness.','original'),
('127.259.d.10.A',3,'The sample space for flipping a coin twice contains how many outcomes?','["4", "3", "2", "8"]'::jsonb,0,'HH, HT, TH, TT.','original'),
('127.259.d.10.A',4,'If P(rain) = 0.3, the probability of the complement (no rain) is:','["0.3", "0.7", "0.03", "1.3"]'::jsonb,1,'1 - 0.3 = 0.7.','original'),
('127.259.d.10.B',3,'If P(A) = 0.4, P(B) = 0.3, and P(A and B) = 0.1, then P(A or B) is:','["0.12", "0.8", "0.6", "0.7"]'::jsonb,2,'0.4 + 0.3 - 0.1 = 0.6.','original'),
('127.259.d.10.B',4,'If P(A and B) = 0.1 and P(B) = 0.4, the conditional probability P(A | B) is:','["4", "0.5", "0.04", "0.25"]'::jsonb,3,'0.1 / 0.4 = 0.25.','original'),
('127.259.d.11',3,'In a binomial setting with n = 3 and p = 0.5, the probability of exactly 2 successes is:','["0.375", "0.25", "0.5", "0.125"]'::jsonb,0,'3 x 0.25 x 0.5 = 0.375.','original'),
('127.259.d.11',4,'The expected number of successes in 10 trials with p = 0.3 is:','["0.3", "3", "10", "7"]'::jsonb,1,'n x p = 3.','original'),
('127.259.d.12',3,'In a normal distribution, about what percent of values lie within one standard deviation of the mean?','["95%", "50%", "68%", "99.7%"]'::jsonb,2,'The empirical rule.','original'),
('127.259.d.12',4,'A test score of 75 has a mean of 70 and a standard deviation of 5. Its z-score is:','["5", "-1", "0.5", "1"]'::jsonb,3,'(75-70)/5 = 1.','original'),
('127.259.d.13.A',3,'The population mean of 2, 4, 6, and 8 is:','["5", "20", "4", "6"]'::jsonb,0,'Sum 20 / 4 = 5.','original'),
('127.259.d.13.A',4,'The population standard deviation of 2, 4, 6, and 8 is closest to:','["1.12", "2.24", "2.5", "5"]'::jsonb,1,'Variance 20/4 = 5; its root is about 2.24.','original'),
('127.259.d.13.B',3,'The standard error of the mean when sigma = 20 and n = 100 is:','["20", "200", "2", "0.2"]'::jsonb,2,'20 / 10 = 2.','original'),
('127.259.d.13.B',4,'If sigma = 12 and n = 16, the standard error is:','["192", "0.75", "12", "3"]'::jsonb,3,'12 / 4 = 3.','original'),
('127.259.d.13.C',3,'A sample of 25 has mean 52 with mu = 50 and sigma = 10. The Z for the sample mean is:','["1", "5", "0.2", "2"]'::jsonb,0,'(52-50)/(10/5) = 1.','original'),
('127.259.d.13.C',4,'A larger sample size makes the standard error:','["Larger", "Smaller", "Unchanged", "Negative"]'::jsonb,1,'SE shrinks with sqrt(n).','original'),
('127.259.d.14.A',3,'A 95% confidence interval for a mean with x-bar 50, sigma 10, n 100 is about:','["45 to 55", "49 to 51", "48.04 to 51.96", "40 to 60"]'::jsonb,2,'50 +/- 1.96 x 1 = 48.04 to 51.96.','original'),
('127.259.d.14.A',4,'When the population standard deviation is unknown and n is small, the interval uses the:','["Normal distribution always", "Uniform distribution", "Binomial distribution", "t distribution"]'::jsonb,3,'Use t with sample s.','original'),
('127.259.d.14.B',3,'Reporting only the confidence level that makes your result look best is:','["Unethical", "Harmless", "Standard practice", "Required"]'::jsonb,0,'Selective reporting misleads.','original'),
('127.259.d.14.B',4,'An ethical report of a confidence interval should state the interval, the confidence level, and the:','["Slogan", "Sample size and method", "Weather", "Author''s age"]'::jsonb,1,'Transparency allows evaluation.','original'),
('127.259.d.15.A',3,'Hypothesis testing uses sample data to decide whether a claim about a population is:','["Always false", "Always true", "Supported or not by evidence", "Impossible to test"]'::jsonb,2,'Tests weigh evidence.','original'),
('127.259.d.15.A',4,'In hypothesis testing, the null hypothesis typically states:','["A guaranteed result", "A prediction of change", "A big effect", "No effect or no difference"]'::jsonb,3,'Null = status quo.','original'),
('127.259.d.15.B',3,'A company claims its bulbs last 1,000 hours on average. A suitable null hypothesis is:','["mu = 1,000", "mu < 1,000", "mu is unknown", "mu > 1,000"]'::jsonb,0,'Null has equality.','original'),
('127.259.d.15.B',4,'If a manager suspects the mean wait is more than 5 minutes, the alternative hypothesis is:','["mu < 5", "mu > 5", "mu = 0", "mu = 5"]'::jsonb,1,'Alternative reflects the suspicion.','original'),
('127.259.d.15.C',3,'A Type I error occurs when we:','["Skip the test", "Accept a false null", "Reject a null hypothesis that is true", "Make a math slip"]'::jsonb,2,'False positive.','original'),
('127.259.d.15.C',4,'A Type II error occurs when we:','["Choose the wrong sample", "Reject a true null", "Misspell the null", "Fail to reject a false null hypothesis"]'::jsonb,3,'False negative.','original'),
('127.259.d.15.D',3,'A significance level of 0.05 means the chance of a Type I error is:','["5%", "50%", "95%", "0.5%"]'::jsonb,0,'Alpha is the Type I risk.','original'),
('127.259.d.15.D',4,'If the power of a test is 0.80, the beta risk is:','["0.05", "0.20", "0.95", "0.80"]'::jsonb,1,'Beta = 1 - power.','original'),
('127.259.d.15.E',3,'The complement of the Type I error probability (1 - alpha) is the:','["Power", "P-value", "Confidence level", "Beta"]'::jsonb,2,'1 - alpha = confidence.','original'),
('127.259.d.15.E',4,'The complement of the Type II error probability (1 - beta) is the:','["Standard error", "Confidence level", "Alpha", "Power of the test"]'::jsonb,3,'Power = 1 - beta.','original'),
('127.259.d.15.F',3,'With x-bar = 105, mu = 100, sigma = 15, and n = 36, the Z statistic is:','["2.0", "0.33", "1.0", "5"]'::jsonb,0,'SE = 2.5; Z = 5/2.5 = 2.','original'),
('127.259.d.15.F',4,'A Z test for a mean requires a known population standard deviation or a:','["Biased sample", "Large sample", "Tiny sample", "Non-random sample"]'::jsonb,1,'Large n allows Z.','original'),
('127.259.d.15.G',3,'For a right-tail test at alpha = 0.05, the critical Z value is about:','["2.58", "0.5", "1.645", "1.96"]'::jsonb,2,'One-tail 5%.','original'),
('127.259.d.15.G',4,'A computed Z of 2.1 in a right-tail test at 0.05 leads to:','["Doubling the sample", "Failing to reject", "Ignoring the result", "Rejecting the null hypothesis"]'::jsonb,3,'2.1 > 1.645.','original'),
('127.259.d.15.H',3,'In a two-tail test at alpha = 0.05, the critical Z values are:','["+/-1.96", "0 only", "+/-1.645", "+/-2.58"]'::jsonb,0,'Split alpha into two tails.','original'),
('127.259.d.15.H',4,'A computed Z of 1.5 in a two-tail test at 0.05 means we:','["Reject the null", "Fail to reject the null hypothesis", "Recompute alpha", "Reject the alternative with certainty"]'::jsonb,1,'1.5 < 1.96.','original'),
('127.259.d.16',3,'Analysis of variance (ANOVA) is used to compare the means of:','["Exactly one group", "Only two groups", "Three or more groups", "No groups"]'::jsonb,2,'ANOVA extends the t test.','original'),
('127.259.d.16',4,'A large F statistic with a small p-value in ANOVA suggests:','["The test failed", "The data are invalid", "All means are equal", "At least one group mean differs"]'::jsonb,3,'Evidence against equal means.','original'),
('127.259.d.17',3,'A chi-square test of independence is used to see whether two:','["Categorical variables are related", "Means are equal", "Medians equal", "Standard deviations match"]'::jsonb,0,'It tests association.','original'),
('127.259.d.17',4,'In a table with row total 40, column total 50, and grand total 200, the expected count is:','["90", "10", "20", "8"]'::jsonb,1,'40 x 50 / 200 = 10.','original'),
('127.259.d.18',3,'Nonparametric tests are useful when data:','["Have no values", "Are missing entirely", "Do not meet normality assumptions", "Are perfectly normal"]'::jsonb,2,'They are distribution-free.','original'),
('127.259.d.18',4,'The sign test and Mann-Whitney test are examples of:','["Regression models", "Parametric tests", "Time series models", "Nonparametric tests"]'::jsonb,3,'Rank/sign tests.','original'),
('127.259.d.19.A',3,'A model with one independent variable predicting a dependent variable is a:','["Simple linear regression", "Time series", "Chi-square", "Pie chart"]'::jsonb,0,'One predictor.','original'),
('127.259.d.19.A',4,'The coefficient of determination (R squared) shows the:','["Slope", "Proportion of variation explained by the model", "Sample size", "Intercept"]'::jsonb,1,'Fit measure.','original'),
('127.259.d.19.B',3,'In y = 2 + 3x, the slope is:','["2", "5", "3", "x"]'::jsonb,2,'Coefficient of x.','original'),
('127.259.d.19.B',4,'In y = 2 + 3x, the intercept is:','["3", "0", "5", "2"]'::jsonb,3,'Value of y at x = 0.','original'),
('127.259.d.19.C',3,'Using y = 2 + 3x, the predicted y when x = 4 is:','["14", "11", "9", "12"]'::jsonb,0,'2 + 12 = 14.','original'),
('127.259.d.19.C',4,'Predicting far outside the range of the original data is risky because the relationship may:','["Be a constant", "Not continue to hold", "Always hold", "Be exact"]'::jsonb,1,'Extrapolation is unreliable.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
