('127.262.d.10.B',3,'A press release is a written announcement sent to:','["The media", "Landlords", "Employees only", "Competitors only"]'::jsonb,0,'PR tool.','original'),
('127.262.d.10.B',4,'A company sponsoring a charity event is engaging in:','["Price cutting", "Public relations", "Product design", "Stocking"]'::jsonb,1,'Builds goodwill.','original'),
('127.262.d.10.C',3,'A coupon is an example of:','["Packaging", "Personal selling", "Sales promotion", "Public relations"]'::jsonb,2,'Short-term incentive.','original'),
