('127.262.d.14.C',4,'A promotional objective should be specific and:','["Vague", "Measurable", "Unlimited", "Secret"]'::jsonb,1,'Measurable goals.','original'),
('127.262.d.14.D',3,'When presenting a marketing plan, a speaker should clearly explain the:','["Seating chart", "Color wheel", "Goals and strategies", "Weather"]'::jsonb,2,'Core content.','original'),
('127.262.d.14.D',4,'Visual aids in a marketing-plan presentation should:','["Replace the talk", "Be unrelated", "Confuse", "Support and clarify key points"]'::jsonb,3,'Aids support.','original'),
('127.262.d.14.E',3,'A marketing plan is effective if it:','["Meets its stated goals", "Is long", "Uses colors", "Looks pretty"]'::jsonb,0,'Results matter.','original'),
